3: #[derive(Debug, Clone, PartialEq, Eq)]
4: pub enum Event {
5:     /// A job was accepted onto the queue.
6:     Queued { id: u32 },
7:     /// A job finished successfully.
8:     Done { id: u32 },
9:     /// A job failed with a message.
10:     Failed { id: u32, why: String },
11: }
12: 
13: impl Event {
14:     /// The job this event is about.
15:     pub fn id(&self) -> u32 {
16:         match self {
17:             Event::Queued { id } => *id,
18:             Event::Done { id } => *id,
19:             Event::Failed { id, .. } => *id,
20:         }
21:     }
22: }

