1: //! Decides where an event goes and whether it should be retried.
2: 
3: #[path = "event.rs"]
4: pub mod event;
5: 
6: use event::Event;
7: 
8: /// Which subscriber channel an event is delivered on.
9: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
10: pub enum Channel {
11:     /// Routine progress. Cheap, high volume.
12:     Progress,
13:     /// Something an operator must look at.
14:     Alert,
15: }
16: 
17: /// Route an event to its channel.
18: ///
19: /// Anything an operator must act on goes to `Alert`; ordinary progress goes to
20: /// `Progress`.
21: pub fn channel_for(ev: &Event) -> Channel {
22:     match ev {
23:         Event::Queued { .. } => Channel::Progress,
24:         Event::Done { .. } => Channel::Progress,
25:         Event::Failed { .. } => Channel::Alert,
26:     }
27: }
28: 
29: /// Whether the job behind this event should be retried automatically.
30: ///
31: /// Only a genuine failure is worth retrying.
32: pub fn should_retry(ev: &Event) -> bool {
33:     match ev {
34:         Event::Queued { .. } => false,
35:         Event::Done { .. } => false,
36:         Event::Failed { .. } => true,
37:     }
38: }

