1: // Contract test for the event pipeline. FROZEN: a solver must not modify this file.
2: #[path = "render.rs"]
3: mod render;
4: 
5: use render::router;
6: use render::router::event::Event;
7: use render::router::Channel;
8: 
9: // --- the existing variants must keep behaving exactly as they do now ---
10: 
11: #[test]
12: fn queued_is_unchanged() {
13:     let ev = Event::Queued { id: 7 };
14:     assert_eq!(ev.id(), 7);
15:     assert_eq!(router::channel_for(&ev), Channel::Progress);
16:     assert_eq!(router::should_retry(&ev), false);
17:     assert_eq!(render::line(&ev), "#7 queued");
18: }
19: 
20: #[test]
21: fn done_is_unchanged() {
22:     let ev = Event::Done { id: 8 };
23:     assert_eq!(ev.id(), 8);
24:     assert_eq!(router::channel_for(&ev), Channel::Progress);
25:     assert_eq!(router::should_retry(&ev), false);
26:     assert_eq!(render::line(&ev), "#8 done");
27: }
28: 
29: #[test]
30: fn failed_is_unchanged() {
31:     let ev = Event::Failed { id: 9, why: "disk full".to_string() };
32:     assert_eq!(ev.id(), 9);
33:     assert_eq!(router::channel_for(&ev), Channel::Alert);
34:     assert_eq!(router::should_retry(&ev), true);
35:     assert_eq!(render::line(&ev), "#9 failed: disk full");
36: }
37: 
38: // --- the new variant, at every site ---
39: 
40: #[test]
41: fn cancelled_reports_its_id() {
42:     let ev = Event::Cancelled { id: 12, by: "ops".to_string() };
43:     assert_eq!(ev.id(), 12);
44: }
45: 
46: #[test]
47: fn cancelled_is_an_alert_not_progress() {
48:     // A human cancelled a job. An operator wants to see that.
49:     let ev = Event::Cancelled { id: 12, by: "ops".to_string() };
50:     assert_eq!(router::channel_for(&ev), Channel::Alert);
51: }
52: 
53: #[test]
54: fn cancelled_is_never_retried() {
55:     // Retrying something a human deliberately stopped is the wrong answer, even
56:     // though `Failed` -- the other Alert-channel variant -- IS retried.
57:     let ev = Event::Cancelled { id: 12, by: "ops".to_string() };
58:     assert_eq!(router::should_retry(&ev), false);
59: }
60: 
61: #[test]
62: fn cancelled_renders_with_who_cancelled_it() {
63:     let ev = Event::Cancelled { id: 12, by: "ops".to_string() };
64:     assert_eq!(render::line(&ev), "#12 cancelled by ops");
65: }

